/* Demonstrates creating, arming, and deleting a POSIX timer (requires linking with -lrt) */
#include <time.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

timer_t global_timerid;
int count = 0;

// Signal handler function triggered when the timer expires
static void timer_handler(int sig, siginfo_t *si, void *uc) {
    if (sig == SIGUSR1) {
        count++;
        printf("Timer expired %d times (PID: %d)\n", count, getpid());

        if (count >= 3) {
            // Delete the timer after 3 expirations and exit
            if (timer_delete(global_timerid) == -1) {
                perror("timer_delete failed");
            }
            printf("Timer deleted. Exiting.\n");
            exit(EXIT_SUCCESS);
        }
    }
}

int main(void) {
    struct sigevent sev;
    struct sigaction sa;
    struct itimerspec its;

    // 1. Configure signal handling (use SIGUSR1)
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // 2. Configure sigevent: Notify via SIGUSR1
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGUSR1;
    sev.sigev_value.sival_ptr = &global_timerid;

    // 3. Create the timer using the Monotonic clock
    if (timer_create(CLOCK_MONOTONIC, &sev, &global_timerid) == -1) {
        perror("timer_create");
        return 1;
    }
    printf("Timer created successfully. ID: %ld\n", (long)global_timerid);

    // 4. Set the timer interval: initial delay 1s, repeat every 1s
    its.it_value.tv_sec = 1;
    its.it_value.tv_nsec = 0;
    its.it_interval.tv_sec = 1;
    its.it_interval.tv_nsec = 0;

    if (timer_settime(global_timerid, 0, &its, NULL) == -1) {
        perror("timer_settime");
        timer_delete(global_timerid); // Cleanup
        return 1;
    }
    printf("Timer armed. Waiting for signals (max 3 times)...\n");

    // Block indefinitely, allowing signals to be processed
    while(1) {
        pause(); 
    }
    return 0;
}
